  const H = CFG.hosts;
  const NOS = CFG.nos;

  /* ---------- CSS global (cards, mapa, modal), injetado uma vez por versão ---------- */
  const injetarCss = () => {
    let tag = document.getElementById('ops-css');
    if (tag && tag.dataset.versao === CFG.versao) {
      return;
    }
    if (!tag) {
      tag = document.createElement('style');
      tag.id = 'ops-css';
