    ]);
    seg += secao('Triggers de segurança', '', listaProblemas(ps), ps.length ? { alerta: true, cor: SEV_COR[ps[0].sev], selo: `${ps.length} ativo${ps.length > 1 ? 's' : ''}` } : {});
    seg += secao(
      'Serviços',
      'SIEM e laboratório de varredura.',
