  }
};
palco.onwheel = (e) => {
  e.preventDefault();
  cancelAnimationFrame(anim);
  const pt = svg.createSVGPoint();
  pt.x = e.clientX;
  pt.y = e.clientY;
  const p = pt.matrixTransform(svg.getScreenCTM().inverse());
  const b = st.vb;
  const nw = Math.min(MUNDO.w * 2.5, Math.max(260, b.w * (e.deltaY > 0 ? 1.15 : 1 / 1.15)));
