/* ---------- Eventos de outros painéis e da URL ---------- */
const aoZoom = (e) => {
  const d = e.detail;
  if (d === 'reset') {
    st.ultimoEnq = null;
    OPS.selecionar('todos');
    voar(MUNDO);
    return;
  }
  const b = st.vb;
  const nw = Math.min(MUNDO.w * 2.5, Math.max(260, b.w * (d > 0 ? 1 / 1.3 : 1.3)));
  const f = nw / b.w;
  voar({ x: b.x + (b.w - nw) / 2, y: b.y + (b.h - b.h * f) / 2, w: nw, h: b.h * f }, 300);
