  // Cache entre painéis: cada painel tem sua janela (1 h, 24 h, 30 dias); o modal aberto por
  // qualquer um deles usa o valor mais recente que algum painel já recebeu.
  const cache = (window.__opsCache = window.__opsCache || {});
  metricas.forEach((m) => {
