  const bytes = (v) => {
    if (vazio(v)) {
      return '—';
    }
    const u = ['B', 'KB', 'MB', 'GB', 'TB'];
    let i = 0;
    let x = Number(v);
    while (x >= 1024 && i < u.length - 1) {
